package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;import java.io.*;import java.util.*;
public class RoadAttributesTest {
 static NativeRoadAttributes helper;static DataOutputStream records;static int cases,accepted,rejected;
 static void emit(int kind,double z0,double z1,int[] raw,int shift,int height,int affine,int near)throws Exception{int[] before=raw.clone();double[] out={0,0};boolean good=true;try{out=kind==0?helper.vertex(z0,raw,shift,height,affine):helper.near(z0,z1,raw,shift,height,affine,near);}catch(IllegalArgumentException expected){good=false;}if(!Arrays.equals(before,raw))throw new AssertionError("Input attributes mutated");records.writeInt(kind);records.writeInt(shift);records.writeInt(height);records.writeInt(affine);records.writeInt(near);records.writeDouble(z0);records.writeDouble(z1);for(int v:raw)records.writeInt(v);records.writeInt(good?1:0);records.writeDouble(out[0]);records.writeDouble(out[1]);cases++;if(good)accepted++;else rejected++;}
 public static void main(String[] args)throws Exception{Path output=Paths.get(args[0]);Files.createDirectories(output);NativeSceneSnapshot snapshot=new NativeSceneSnapshot(Files.readAllBytes(Paths.get(args[1])));NativeWorldScene world=new NativeWorldScene(snapshot.geometry(0));ByteBuffer input=world.reciprocal();byte[] table=new byte[input.remaining()];input.get(table);Files.write(output.resolve("reciprocal.bin"),table);helper=new NativeRoadAttributes(ByteBuffer.wrap(table));
  ByteArrayOutputStream bytes=new ByteArrayOutputStream();records=new DataOutputStream(bytes);int[][] attrs={{0,0,0,0},{1,-1,16384,-16384},{Integer.MIN_VALUE,Integer.MAX_VALUE,Integer.MAX_VALUE,Integer.MIN_VALUE},{0x7fffff80,0x80000080,0xf0000000,0x0fffffff}};
  for(int affine=0;affine<2;affine++)for(int[] raw:attrs){for(double z:new double[]{1,1.00000001,63,63.5,64,64.00001,16384.25,32767})emit(0,z,0,raw,6,128,affine,64);for(double[] edge:new double[][]{{32,96},{96,32},{63.25,64.75},{64.75,63.25},{-100.125,200.875},{63.9999,64.0001}})emit(1,edge[0],edge[1],raw,6,128,affine,64);}
  Random random=new Random(3841);for(int i=0;i<400;i++){int[] raw={random.nextInt(),random.nextInt(),random.nextInt(),random.nextInt()};int shift=random.nextInt(11),height=2*(1+random.nextInt(1024)),affine=random.nextInt(2);emit(0,1+random.nextDouble()*32766,0,raw,shift,height,affine,64);double behind=64-random.nextDouble()*1500,front=64+random.nextDouble()*1500;emit(1,i%2==0?behind:front,i%2==0?front:behind,raw,shift,height,affine,64);}
  int[] raw=attrs[1];for(double bad:new double[]{Double.NaN,Double.POSITIVE_INFINITY,0,32767.5})emit(0,bad,0,raw,6,128,0,64);for(double[] edge:new double[][]{{100,200},{-20,-10},{64,65},{Double.NaN,100},{-32768,32767}})emit(1,edge[0],edge[1],raw,6,128,0,64);emit(0,64,0,raw,11,128,0,64);emit(0,64,0,raw,6,3,0,64);emit(1,32,96,raw,6,128,2,64);
  int fixture=0;try(DirectoryStream<Path> files=Files.newDirectoryStream(Paths.get(args[2]),"*.nsp")){for(Path file:files){if(file.getFileName().toString().startsWith("bad-"))continue;NativeWorldScene w=new NativeWorldScene(new NativeScenePacket(1,Files.readAllBytes(file)));for(int si=0;si<w.surfaceCount();si++){ByteBuffer source=w.surface(si).sourceAttributes();if(source==null)continue;fixture++;int count=source.getInt(0),shift=source.getInt(4),height=source.getInt(8),affine=source.getInt(12);for(int i=0;i<count;i++){int next=(i+1)%count;int[] a={source.getInt(32+i*8),source.getInt(36+i*8),source.getInt(32+next*8),source.getInt(36+next*8)};emit(0,64.25,0,a,shift,height,affine,64);emit(1,32.125,100.75,a,shift,height,affine,64);}}}}
  records.close();try(DataOutputStream out=new DataOutputStream(Files.newOutputStream(output.resolve("road-attribute-cases.bin")))){out.writeInt(0x3141524e);out.writeInt(cases);out.write(bytes.toByteArray());}if(accepted==0||rejected==0||fixture!=4)throw new AssertionError("Missing attribute cases");System.out.println("PASS_ROAD_ATTRIBUTE_CASES cases="+cases+" accepted="+accepted+" rejected="+rejected+" fixture_surfaces="+fixture+" input_immutable=true");
 }
}
